<?php
declare(strict_types=1);
namespace App\Repositories;
use PDO;
final class AcademicHistoryRepository {
 public function __construct(private PDO $db){}
 public function student(int $id):?array{$s=$this->db->prepare("SELECT e.id,e.codigo_estudiante,p.numero_identificacion,CONCAT_WS(' ',p.primer_nombre,p.segundo_nombre,p.primer_apellido,p.segundo_apellido) nombre FROM estudiantes e JOIN personas p ON p.id=e.persona_id WHERE e.id=:id AND e.deleted_at IS NULL");$s->execute(['id'=>$id]);return$s->fetch()?:null;}
 public function trajectories(int $student):array{$s=$this->db->prepare("SELECT ec.id,c.nombre carrera,mc.codigo malla_codigo,mc.nombre malla,et.nombre estado,ec.fecha_inicio,ec.fecha_fin,se.nombre sede,mo.nombre modalidad FROM estudiante_carreras ec JOIN carreras c ON c.id=ec.carrera_id JOIN mallas_curriculares mc ON mc.id=ec.malla_id JOIN estados_trayectoria_academica et ON et.id=ec.estado_trayectoria_id LEFT JOIN sedes se ON se.id=ec.sede_id LEFT JOIN modalidades_academicas mo ON mo.id=ec.modalidad_academica_id WHERE ec.estudiante_id=:e AND ec.deleted_at IS NULL ORDER BY ec.fecha_inicio,ec.id");$s->execute(['e'=>$student]);return$s->fetchAll();}
 public function enrollments(int $student):array{$s=$this->db->prepare("SELECT m.id,m.estudiante_carrera_id,m.numero_matricula,m.periodo_academico_id,pa.codigo periodo_codigo,pa.nombre periodo,pa.fecha_inicio,pa.fecha_fin,em.codigo estado_codigo,em.nombre estado,COUNT(ma.id) asignaturas FROM matriculas m JOIN estudiante_carreras ec ON ec.id=m.estudiante_carrera_id JOIN periodos_academicos pa ON pa.id=m.periodo_academico_id JOIN estados_matricula em ON em.id=m.estado_matricula_id LEFT JOIN matricula_asignaturas ma ON ma.matricula_id=m.id WHERE ec.estudiante_id=:e AND ec.deleted_at IS NULL GROUP BY m.id,m.estudiante_carrera_id,m.numero_matricula,m.periodo_academico_id,pa.codigo,pa.nombre,pa.fecha_inicio,pa.fecha_fin,em.codigo,em.nombre ORDER BY pa.fecha_inicio,m.id");$s->execute(['e'=>$student]);return$s->fetchAll();}
 public function subjects(int $student):array{$s=$this->db->prepare("SELECT ma.id,ma.matricula_id,ma.numero_intento,ma.materia_pendiente,ma.reconocimiento_aplicado,ma.observacion,ema.codigo estado_codigo,ema.nombre estado,a.codigo asignatura_codigo,a.nombre asignatura,n.nombre nivel,qn.source_grade_id,qn.nota_ordinaria,qn.nota_supletorio,qn.nota_final,qn.inasistencias_acumuladas,qn.observaciones observaciones_q10,CASE WHEN qn.id IS NULL THEN 0 ELSE 1 END es_historico_q10 FROM matricula_asignaturas ma JOIN matriculas m ON m.id=ma.matricula_id JOIN estudiante_carreras ec ON ec.id=m.estudiante_carrera_id JOIN estados_matricula_asignatura ema ON ema.id=ma.estado_matricula_asignatura_id JOIN malla_asignaturas mas ON mas.id=ma.malla_asignatura_id JOIN asignaturas a ON a.id=mas.asignatura_id JOIN niveles_academicos n ON n.id=mas.nivel_academico_id LEFT JOIN migracion_q10_historico_notas qn ON qn.matricula_asignatura_id=ma.id AND qn.estado='IMPORTADO' WHERE ec.estudiante_id=:e AND ec.deleted_at IS NULL ORDER BY m.periodo_academico_id,n.orden_nivel,mas.orden_en_nivel,a.nombre,ma.id");$s->execute(['e'=>$student]);return$s->fetchAll();}
 public function gradeDetails(int $student):array{$s=$this->db->prepare("SELECT cr.matricula_asignatura_id,peval.nombre parcial,peval.orden_visual parcial_orden,pe.nombre parametro,pe.orden_visual parametro_orden,re.id recurso_id,re.nombre recurso,cr.nota_obtenida,cr.nota_maxima,oc.codigo origen_calificacion,ore.codigo origen_recurso FROM calificaciones_recursos cr JOIN matricula_asignaturas ma ON ma.id=cr.matricula_asignatura_id JOIN matriculas m ON m.id=ma.matricula_id JOIN estudiante_carreras ec ON ec.id=m.estudiante_carrera_id JOIN recursos_evaluables re ON re.id=cr.recurso_id JOIN origenes_recurso_evaluable ore ON ore.id=re.origen_recurso_id JOIN origenes_calificacion oc ON oc.id=cr.origen_calificacion_id LEFT JOIN recurso_parametro_evaluacion rpe ON rpe.recurso_id=re.id AND rpe.activo=1 LEFT JOIN parametros_evaluacion pe ON pe.id=rpe.parametro_evaluacion_id LEFT JOIN parciales_evaluacion peval ON peval.id=pe.parcial_id WHERE ec.estudiante_id=:e AND ec.deleted_at IS NULL ORDER BY cr.matricula_asignatura_id,COALESCE(peval.orden_visual,999),COALESCE(pe.orden_visual,999),re.id");$s->execute(['e'=>$student]);$out=[];foreach($s->fetchAll() as $r)$out[(int)$r['matricula_asignatura_id']][]=$r;return$out;}
}
